//! Reads the vendored androidx token files.
//!
//! They are Kotlin generated by Google's token tooling, so their shape is small and regular: a header, then one
//! `internal object <Name> { ... }` holding `const val` numbers, `inline val` getters and `val` shapes. One file,
//! `TypographyTokens.kt`, is instead an `internal class` of text styles, followed by the default style they copy. This
//! reader accepts exactly the forms listed in [`Value`] and rejects every other line with its number, so a form it
//! does not know is never skipped or guessed: support for it is added on purpose, with a test.

use std::collections::HashSet;
use std::fmt;

/// One token file: `internal object <name> { ... }`.
#[derive(Debug, PartialEq)]
pub(crate) struct TokenObject {
    /// The object's name, such as `MotionTokens`.
    pub(crate) name: String,
    /// The `// VERSION:` header, such as `v0_103`, when the file has one.
    pub(crate) version: Option<String>,
    /// The tokens, in file order.
    pub(crate) tokens: Vec<Token>,
}

/// One token: a name and its value.
#[derive(Debug, PartialEq)]
pub(crate) struct Token {
    /// The Kotlin name, such as `DurationShort1`.
    pub(crate) name: String,
    /// The value.
    pub(crate) value: Value,
}

/// The token values this reader understands.
#[derive(Debug, Clone, PartialEq)]
pub(crate) enum Value {
    /// `const val X = 0.8f` (a Kotlin `Float`) or `const val X = 700.0` (a Kotlin `Double` that `f32` holds
    /// exactly; NSH takes `f32`).
    Number(f32),
    /// `inline val X: CubicBezierEasing` / `get() = CubicBezierEasing(x1, y1, x2, y2)`.
    CubicBezier([f32; 4]),
    /// `inline val X: Color` / `get() = Color(red = 0, green = 0, blue = 0)`: an opaque 8-bit sRGB color.
    Srgb([u8; 3]),
    /// `inline val X: androidx.compose.ui.unit.Dp` / `get() = 6.0.dp`, or `val X = CornerSize(4.0.dp)`: a length in
    /// density-independent pixels, which is NSH's point.
    Dp(f32),
    /// `val X = RectangleShape`, `val X = CircleShape` or `val X = RoundedCornerShape(...)`, on one line or over
    /// several.
    Shape(Shape),
    /// `inline val X: androidx.compose.ui.unit.TextUnit` / `get() = 16.sp` or `get() = 0.5.sp`: a text size in
    /// scaled pixels, as the `Float` androidx makes of the number.
    Sp(f32),
    /// `inline val X: FontFamily` / `get() = FontFamily.SansSerif`.
    FontFamily(FontFamily),
    /// `inline val X: FontWeight` / `get() = FontWeight.Medium`: the weight, from 100 to 900.
    FontWeight(u16),
    /// `val X = ColorToken(25)` in a file of keys: a key, named by its class (`ColorToken`). Its number is
    /// androidx's internal id and is not kept.
    Key(String),
    /// `inline val X: androidx.compose.ui.graphics.Color` / `get() = PaletteTokens.Neutral98`: the value of another
    /// token, of another object or, written `get() = Primary`, of the same one. The getter's type says what kind of
    /// value it is.
    Reference(Kind, Reference),
    /// `val X: TextStyle` / `inline get() =` / `DefaultTextStyle.copy(` and the five properties of the type scale
    /// style of the same name, one per line, then `)`: a text style. Boxed: its ten names would make every value
    /// as large.
    TextStyle(Box<TextStyle>),
}

/// A text style of `TypographyTokens`: the five tokens of the type scale style of its name.
///
/// androidx writes `fontFamily = fontFamily ?: TypeScaleTokens.BodyLargeFont`: an app may give `Typography` a font
/// family of its own. The library has no such parameter, so it keeps the token.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct TextStyle {
    /// `fontFamily`, such as `TypeScaleTokens.BodyLargeFont`.
    pub(crate) font: Reference,
    /// `fontWeight`.
    pub(crate) weight: Reference,
    /// `fontSize`.
    pub(crate) size: Reference,
    /// `lineHeight`.
    pub(crate) line_height: Reference,
    /// `letterSpacing`, the type scale's tracking.
    pub(crate) tracking: Reference,
}

impl TextStyle {
    /// Each property with the kind of value its token must be.
    pub(crate) fn properties(&self) -> [(Kind, &Reference); 5] {
        [
            (Kind::FontFamily, &self.font),
            (Kind::FontWeight, &self.weight),
            (Kind::TextUnit, &self.size),
            (Kind::TextUnit, &self.line_height),
            (Kind::TextUnit, &self.tracking),
        ]
    }
}

/// What a [`Value::Reference`] names, from the getter's type.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Kind {
    /// `Color`: a color, or a reference to one.
    Color,
    /// `FontFamily`: a font family, or a reference to one.
    FontFamily,
    /// `FontWeight`: a font weight, or a reference to one.
    FontWeight,
    /// `androidx.compose.ui.unit.Dp`: a length, or a reference to one (`ElevationTokens.Level1`).
    Length,
    /// `androidx.compose.ui.unit.TextUnit`: a text size, line height or tracking in sp. Only a text style names one.
    TextUnit,
    /// `ColorToken`: a key of `ColorSchemeKeyTokens`, a color role of the scheme.
    ColorRole,
    /// `ShapeToken`: a key of `ShapeKeyTokens`, which names the shape of the same name in `ShapeTokens`.
    ShapeKey,
    /// `TypographyToken`: a key of `TypographyKeyTokens`, which names the text style of the same name in
    /// `TypographyTokens`.
    TypographyKey,
}

impl Kind {
    /// Whether `value` is a value of this kind, so that a reference of this kind may name it.
    pub(crate) fn holds(self, value: &Value) -> bool {
        match (self, value) {
            (Self::Color, Value::Srgb(_))
            | (Self::FontFamily, Value::FontFamily(_))
            | (Self::FontWeight, Value::FontWeight(_))
            | (Self::Length, Value::Dp(_))
            | (Self::TextUnit, Value::Sp(_)) => true,
            (Self::ColorRole, Value::Key(class)) => class == "ColorToken",
            (Self::ShapeKey, Value::Key(class)) => class == "ShapeToken",
            (Self::TypographyKey, Value::Key(class)) => class == "TypographyToken",
            (kind, Value::Reference(other, _)) => kind == *other,
            _ => false,
        }
    }
}

impl fmt::Display for Kind {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            Self::Color => "color",
            Self::FontFamily => "font family",
            Self::FontWeight => "font weight",
            Self::Length => "length",
            Self::TextUnit => "text unit",
            Self::ColorRole => "color role",
            Self::ShapeKey => "shape key",
            Self::TypographyKey => "typography key",
        })
    }
}

/// A generic font family: androidx `FontFamily.SansSerif`, the one these files use.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum FontFamily {
    /// `FontFamily.SansSerif`.
    SansSerif,
}

/// A shape, as androidx builds one.
#[derive(Debug, Clone, PartialEq)]
pub(crate) enum Shape {
    /// `RectangleShape`: square corners.
    Rectangle,
    /// `CircleShape`: each corner rounded by half the shorter side.
    Circle,
    /// `RoundedCornerShape(4.0.dp)`, the same radius at every corner, or `RoundedCornerShape(topStart = 4.0.dp,
    /// topEnd = 4.0.dp, bottomEnd = 0.0.dp, bottomStart = 0.0.dp)`: the radius at each corner, in that order.
    Rounded([f32; 4]),
}

/// A token of another object, such as `PaletteTokens.Neutral98`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct Reference {
    /// The object, such as `PaletteTokens`.
    pub(crate) object: String,
    /// The token, such as `Neutral98`.
    pub(crate) token: String,
}

/// Why a file was rejected, and on which line (1-based).
#[derive(Debug, PartialEq)]
pub(crate) struct ParseError {
    pub(crate) line: usize,
    pub(crate) kind: ParseErrorKind,
}

#[derive(Debug, PartialEq)]
pub(crate) enum ParseErrorKind {
    /// A line whose form this reader does not support.
    Unsupported(String),
    /// A token name that is not a plain `PascalCase` identifier.
    BadName(String),
    /// A number that is not a plain decimal literal, or an integer.
    BadNumber(String),
    /// A color channel that is not a plain integer from 0 to 255.
    BadChannel(String),
    /// A `Double` that `f32` cannot hold exactly.
    Inexact(String),
    /// An `inline val` not followed by its `get() = ...` line.
    MissingGetter(String),
    /// A `val X =` whose value never closes its parentheses.
    UnclosedValue(String),
    /// The same token name twice.
    Duplicate(String),
    /// Something after the object's closing brace.
    TrailingContent(String),
    /// The file has no `internal object`, or it never closes.
    Unterminated,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "line {}: ", self.line)?;
        match &self.kind {
            ParseErrorKind::Unsupported(text) => write!(f, "unsupported form `{text}`"),
            ParseErrorKind::BadName(name) => write!(f, "`{name}` is not a PascalCase token name"),
            ParseErrorKind::BadNumber(text) => write!(f, "`{text}` is not a supported number"),
            ParseErrorKind::BadChannel(text) => {
                write!(f, "`{text}` is not a color channel from 0 to 255")
            }
            ParseErrorKind::Inexact(text) => write!(f, "`{text}` cannot be held exactly by an f32"),
            ParseErrorKind::MissingGetter(name) => write!(f, "`{name}` has no `get() = ...` line"),
            ParseErrorKind::UnclosedValue(name) => write!(f, "`{name}`'s value never closes"),
            ParseErrorKind::Duplicate(name) => write!(f, "`{name}` is defined twice"),
            ParseErrorKind::TrailingContent(text) => write!(f, "`{text}` after the object's end"),
            ParseErrorKind::Unterminated => write!(f, "no complete `internal object` in the file"),
        }
    }
}

enum State {
    Header,
    Body,
    Getter {
        name: String,
        ty: String,
    },
    /// Inside `val <name> =`, whose value spans lines: `expression` holds them so far, trimmed and joined.
    Value {
        name: String,
        expression: String,
    },
    /// Inside `val <name>: TextStyle`: `properties` holds the tokens read so far, in [`TEXT_STYLE_PROPERTIES`] order,
    /// and `line` is the index in [`TEXT_STYLE_LINES`] of the line that comes next.
    TextStyle {
        name: String,
        line: usize,
        properties: Vec<Reference>,
    },
    /// After the object's closing brace: `line` lines of [`DEFAULT_TEXT_STYLE`] have been read.
    Done {
        line: usize,
    },
}

/// The lines between `val <name>: TextStyle` and its five properties.
const TEXT_STYLE_LINES: [&str; 2] = ["inline get() =", "DefaultTextStyle.copy("];

/// Each property line of a text style, before its token, and the end of that token's name: `fontWeight =
/// TypeScaleTokens.BodyLargeWeight,` in `BodyLarge`.
const TEXT_STYLE_PROPERTIES: [(&str, &str); 5] = [
    ("fontFamily = fontFamily ?: ", "Font"),
    ("fontWeight = ", "Weight"),
    ("fontSize = ", "Size"),
    ("lineHeight = ", "LineHeight"),
    ("letterSpacing = ", "Tracking"),
];

/// What may follow the closing brace of `TypographyTokens`, and nothing else: the style each text style copies. It
/// centers a line's text in its line height and trims nothing; no token depends on it.
const DEFAULT_TEXT_STYLE: [&str; 7] = [
    "internal val DefaultLineHeightStyle =",
    "LineHeightStyle(alignment = LineHeightStyle.Alignment.Center, trim = LineHeightStyle.Trim.None)",
    "internal val DefaultTextStyle =",
    "TextStyle.Default.copy(",
    "platformStyle = defaultPlatformTextStyle(),",
    "lineHeightStyle = DefaultLineHeightStyle,",
    ")",
];

/// Reads one token file.
pub(crate) fn parse(source: &str) -> Result<TokenObject, ParseError> {
    let mut object = TokenObject {
        name: String::new(),
        version: None,
        tokens: Vec::new(),
    };
    let mut seen = HashSet::new();
    let mut state = State::Header;
    let mut last_line = 0;
    for (index, raw) in source.lines().enumerate() {
        let line = index + 1;
        last_line = line;
        let text = raw.trim();
        let error = |kind| ParseError { line, kind };
        state = match state {
            State::Header => header_line(text, &mut object).map_err(error)?,
            State::Body => match body_line(text).map_err(error)? {
                BodyLine::Blank => State::Body,
                BodyLine::End => State::Done { line: 0 },
                BodyLine::TextStyle { name } => State::TextStyle {
                    name,
                    line: 0,
                    properties: Vec::new(),
                },
                BodyLine::Token(token) => {
                    push(&mut object, &mut seen, token).map_err(error)?;
                    State::Body
                }
                BodyLine::Getter { name, ty } => State::Getter { name, ty },
                BodyLine::Value { name } => State::Value {
                    name,
                    expression: String::new(),
                },
            },
            State::Getter { name, ty } => {
                let token = getter_line(text, name, &ty, &object.name).map_err(error)?;
                push(&mut object, &mut seen, token).map_err(error)?;
                State::Body
            }
            State::Value {
                name,
                mut expression,
            } => {
                expression.push_str(text);
                if is_closed(&expression) {
                    let value = value_expression(&expression).map_err(error)?;
                    push(&mut object, &mut seen, Token { name, value }).map_err(error)?;
                    State::Body
                } else {
                    State::Value { name, expression }
                }
            }
            State::TextStyle {
                name,
                line: step,
                properties,
            } => match text_style_line(text, name, step, properties).map_err(error)? {
                Ok(next) => next,
                Err(token) => {
                    push(&mut object, &mut seen, token).map_err(error)?;
                    State::Body
                }
            },
            State::Done { line: read } if text.is_empty() => State::Done { line: read },
            State::Done { line: read } => {
                if DEFAULT_TEXT_STYLE.get(read) != Some(&text) {
                    return Err(error(ParseErrorKind::TrailingContent(text.to_owned())));
                }
                State::Done { line: read + 1 }
            }
        };
    }
    match state {
        // The default style comes whole or not at all.
        State::Done { line: 0 } => Ok(object),
        State::Done { line } if line == DEFAULT_TEXT_STYLE.len() => Ok(object),
        State::Done { .. } => Err(ParseError {
            line: last_line,
            kind: ParseErrorKind::UnclosedValue("DefaultTextStyle".to_owned()),
        }),
        State::Getter { name, .. } => Err(ParseError {
            line: last_line,
            kind: ParseErrorKind::MissingGetter(name),
        }),
        State::Value { name, .. } | State::TextStyle { name, .. } => Err(ParseError {
            line: last_line,
            kind: ParseErrorKind::UnclosedValue(name),
        }),
        State::Header | State::Body => Err(ParseError {
            line: last_line,
            kind: ParseErrorKind::Unterminated,
        }),
    }
}

fn header_line(text: &str, object: &mut TokenObject) -> Result<State, ParseErrorKind> {
    if let Some(version) = text.strip_prefix("// VERSION:") {
        object.version = Some(version.trim().to_owned());
        return Ok(State::Header);
    }
    let is_comment = text.starts_with("/*") || text.starts_with('*') || text.starts_with("//");
    // The class of a file of keys: `@JvmInline internal value class ColorToken(val id: Int)`.
    let is_key_class = text
        .strip_prefix("@JvmInline internal value class ")
        .and_then(|rest| rest.strip_suffix("(val id: Int)"))
        .is_some_and(|class| checked_name(class).is_ok() && class.ends_with("Token"));
    if is_key_class {
        return Ok(State::Header);
    }
    if text.is_empty() || is_comment || text.starts_with("package ") || text.starts_with("import ")
    {
        return Ok(State::Header);
    }
    // `TypographyTokens` is a class whose one parameter is the font family an app may give `Typography`.
    let name = text
        .strip_prefix("internal object ")
        .and_then(|rest| rest.strip_suffix(" {"))
        .or_else(|| {
            text.strip_prefix("internal class ")
                .and_then(|rest| rest.strip_suffix("(val fontFamily: FontFamily? = null) {"))
        })
        .ok_or_else(|| ParseErrorKind::Unsupported(text.to_owned()))?;
    object.name = checked_name(name)?;
    Ok(State::Body)
}

enum BodyLine {
    Blank,
    End,
    Token(Token),
    Getter {
        name: String,
        ty: String,
    },
    /// `val <name> =`, its value on the lines after.
    Value {
        name: String,
    },
    /// `val <name>: TextStyle`, its getter on the lines after.
    TextStyle {
        name: String,
    },
}

fn body_line(text: &str) -> Result<BodyLine, ParseErrorKind> {
    // A line comment holds no token (`TypeScaleTokens` has one, a note above its emphasized styles).
    if text.is_empty() || text.starts_with("//") {
        return Ok(BodyLine::Blank);
    }
    if text == "}" {
        return Ok(BodyLine::End);
    }
    if let Some(rest) = text.strip_prefix("const val ") {
        let (name, literal) = rest
            .split_once(" = ")
            .ok_or_else(|| ParseErrorKind::Unsupported(text.to_owned()))?;
        return Ok(BodyLine::Token(Token {
            name: checked_name(name)?,
            value: Value::Number(number(literal)?),
        }));
    }
    if let Some(rest) = text.strip_prefix("inline val ") {
        let (name, ty) = rest
            .split_once(": ")
            .ok_or_else(|| ParseErrorKind::Unsupported(text.to_owned()))?;
        return Ok(BodyLine::Getter {
            name: checked_name(name)?,
            ty: ty.to_owned(),
        });
    }
    if let Some(rest) = text.strip_prefix("val ") {
        if let Some(name) = rest.strip_suffix(": TextStyle") {
            return Ok(BodyLine::TextStyle {
                name: checked_name(name)?,
            });
        }
        if let Some(name) = rest.strip_suffix(" =") {
            return Ok(BodyLine::Value {
                name: checked_name(name)?,
            });
        }
        let (name, expression) = rest
            .split_once(" = ")
            .ok_or_else(|| ParseErrorKind::Unsupported(text.to_owned()))?;
        let name = checked_name(name)?;
        // A value that opens a parenthesis it does not close on this line is not a form these files use.
        if !is_closed(expression) {
            return Err(ParseErrorKind::Unsupported(text.to_owned()));
        }
        let value = value_expression(expression).map_err(|error| match error {
            ParseErrorKind::Unsupported(_) => ParseErrorKind::Unsupported(text.to_owned()),
            other => other,
        })?;
        return Ok(BodyLine::Token(Token { name, value }));
    }
    Err(ParseErrorKind::Unsupported(text.to_owned()))
}

/// Whether `expression` is complete: not empty, and every parenthesis it opens is closed.
fn is_closed(expression: &str) -> bool {
    !expression.is_empty() && expression.matches('(').count() == expression.matches(')').count()
}

/// The value of a `val`: a shape or a corner size.
fn value_expression(expression: &str) -> Result<Value, ParseErrorKind> {
    let unsupported = || ParseErrorKind::Unsupported(expression.to_owned());
    match expression {
        "RectangleShape" => return Ok(Value::Shape(Shape::Rectangle)),
        "CircleShape" => return Ok(Value::Shape(Shape::Circle)),
        _ => {}
    }
    if let Some(key) = key(expression) {
        return Ok(key);
    }
    if let Some(argument) = expression
        .strip_prefix("CornerSize(")
        .and_then(|rest| rest.strip_suffix(')'))
    {
        return Ok(Value::Dp(dp(argument).ok_or_else(unsupported)??));
    }
    let arguments = expression
        .strip_prefix("RoundedCornerShape(")
        .and_then(|rest| rest.strip_suffix(')'))
        .ok_or_else(unsupported)?;
    // Kotlin allows a trailing comma, and the generated files put one after the last named argument.
    let arguments: Vec<&str> = arguments
        .strip_suffix(',')
        .unwrap_or(arguments)
        .split(',')
        .map(str::trim)
        .collect();
    // One argument is the radius of every corner, unless it is named: one named corner is not a form these files use.
    let radii = if let [radius] = arguments.as_slice()
        && !radius.contains('=')
    {
        let radius = dp(radius).ok_or_else(unsupported)??;
        [radius; 4]
    } else {
        let labels = ["topStart = ", "topEnd = ", "bottomEnd = ", "bottomStart = "];
        if arguments.len() != labels.len() {
            return Err(unsupported());
        }
        let mut radii = [0.0; 4];
        for ((radius, argument), label) in radii.iter_mut().zip(&arguments).zip(labels) {
            let length = argument.strip_prefix(label).ok_or_else(unsupported)?;
            *radius = dp(length).ok_or_else(unsupported)??;
        }
        radii
    };
    Ok(Value::Shape(Shape::Rounded(radii)))
}

/// Line `step` after `val <name>: TextStyle`, with the properties read so far: the state that reads the next line,
/// or, at the closing `)`, the finished token.
fn text_style_line(
    text: &str,
    name: String,
    step: usize,
    mut properties: Vec<Reference>,
) -> Result<Result<State, Token>, ParseErrorKind> {
    let unsupported = || ParseErrorKind::Unsupported(text.to_owned());
    if let Some(expected) = TEXT_STYLE_LINES.get(step) {
        if text != *expected {
            return Err(unsupported());
        }
    } else if let Some(&(label, suffix)) = TEXT_STYLE_PROPERTIES.get(properties.len()) {
        properties.push(text_style_property(text, label, &name, suffix)?);
    } else if text == ")" {
        return Ok(Err(Token {
            name,
            value: text_style(properties)?,
        }));
    } else {
        return Err(unsupported());
    }
    Ok(Ok(State::TextStyle {
        name,
        line: step + 1,
        properties,
    }))
}

/// One property line of the text style `style`: `label`, then a token of another object whose name is the style's
/// and `suffix` (`TypeScaleTokens.BodyLargeWeight`), then a comma. A token of another style, of this object, or
/// any other expression is refused.
fn text_style_property(
    text: &str,
    label: &str,
    style: &str,
    suffix: &str,
) -> Result<Reference, ParseErrorKind> {
    let unsupported = || ParseErrorKind::Unsupported(text.to_owned());
    let expression = text
        .strip_prefix(label)
        .and_then(|rest| rest.strip_suffix(','))
        .ok_or_else(unsupported)?;
    if !expression.contains('.') {
        return Err(unsupported());
    }
    let reference = reference(expression, "").ok_or_else(unsupported)??;
    if reference.token.strip_suffix(suffix) != Some(style) {
        return Err(unsupported());
    }
    Ok(reference)
}

/// The text style of five properties read in [`TEXT_STYLE_PROPERTIES`] order, all tokens of one object.
fn text_style(properties: Vec<Reference>) -> Result<Value, ParseErrorKind> {
    let Ok([font, weight, size, line_height, tracking]) = <[Reference; 5]>::try_from(properties)
    else {
        return Err(ParseErrorKind::Unsupported(")".to_owned()));
    };
    let style = TextStyle {
        font,
        weight,
        size,
        line_height,
        tracking,
    };
    let object = &style.font.object;
    if style
        .properties()
        .iter()
        .any(|(_, reference)| &reference.object != object)
    {
        return Err(ParseErrorKind::Unsupported(format!(
            "a text style whose tokens are not all of `{object}`"
        )));
    }
    Ok(Value::TextStyle(Box::new(style)))
}

/// `ColorToken(25)`, a key of the class `ColorToken`; `None` for any other form.
fn key(expression: &str) -> Option<Value> {
    let (class, rest) = expression.split_once('(')?;
    let id = rest.strip_suffix(')')?;
    let is_key = class.ends_with("Token")
        && checked_name(class).is_ok()
        && !id.is_empty()
        && id.chars().all(|c| c.is_ascii_digit());
    is_key.then(|| Value::Key(class.to_owned()))
}

/// `4.0.dp`, as a number of points; `None` when the expression is not a length in dp.
fn dp(expression: &str) -> Option<Result<f32, ParseErrorKind>> {
    expression.strip_suffix(".dp").map(number)
}

/// The value of `inline val <name>: <ty>`, from its `get() = ...` line, in the object named `object`.
fn getter_line(text: &str, name: String, ty: &str, object: &str) -> Result<Token, ParseErrorKind> {
    let Some(expression) = text.strip_prefix("get() = ") else {
        return Err(ParseErrorKind::MissingGetter(name));
    };
    let unsupported = || ParseErrorKind::Unsupported(text.to_owned());
    let value = match ty {
        "CubicBezierEasing" => curve(expression).ok_or_else(unsupported)??,
        "Color" | "androidx.compose.ui.graphics.Color" => match srgb(expression) {
            Some(channels) => Value::Srgb(channels?),
            None => Value::Reference(
                Kind::Color,
                reference(expression, object).ok_or_else(unsupported)??,
            ),
        },
        "androidx.compose.ui.unit.Dp" => match dp(expression) {
            Some(length) => Value::Dp(length?),
            // A number with no unit is not a length, and not a reference either.
            None if expression.starts_with(|c: char| c.is_ascii_digit() || c == '-') => {
                return Err(unsupported());
            }
            None => Value::Reference(
                Kind::Length,
                reference(expression, object).ok_or_else(unsupported)??,
            ),
        },
        // A key always names its key object: a bare name would be a token of this object, never a key.
        "ColorToken" if expression.starts_with("ColorSchemeKeyTokens.") => Value::Reference(
            Kind::ColorRole,
            reference(expression, object).ok_or_else(unsupported)??,
        ),
        "ShapeToken" if expression.starts_with("ShapeKeyTokens.") => Value::Reference(
            Kind::ShapeKey,
            reference(expression, object).ok_or_else(unsupported)??,
        ),
        "TypographyToken" if expression.starts_with("TypographyKeyTokens.") => Value::Reference(
            Kind::TypographyKey,
            reference(expression, object).ok_or_else(unsupported)??,
        ),
        "androidx.compose.ui.unit.TextUnit" => {
            let literal = expression.strip_suffix(".sp").ok_or_else(unsupported)?;
            Value::Sp(sp(literal)?)
        }
        "FontFamily" | "androidx.compose.ui.text.font.FontFamily" => match expression {
            "FontFamily.SansSerif" => Value::FontFamily(FontFamily::SansSerif),
            // Another generic family is a value this reader does not know, not a token of an object `FontFamily`.
            _ if expression.starts_with("FontFamily.") => return Err(unsupported()),
            _ => Value::Reference(
                Kind::FontFamily,
                reference(expression, object).ok_or_else(unsupported)??,
            ),
        },
        "FontWeight" | "androidx.compose.ui.text.font.FontWeight" => match expression {
            // androidx `FontWeight.kt`: `Normal = W400`, `Medium = W500`, `Bold = W700`.
            "FontWeight.Normal" => Value::FontWeight(400),
            "FontWeight.Medium" => Value::FontWeight(500),
            "FontWeight.Bold" => Value::FontWeight(700),
            _ if expression.starts_with("FontWeight.") => return Err(unsupported()),
            _ => Value::Reference(
                Kind::FontWeight,
                reference(expression, object).ok_or_else(unsupported)??,
            ),
        },
        _ => return Err(unsupported()),
    };
    Ok(Token { name, value })
}

/// `CubicBezierEasing(x1, y1, x2, y2)`; `None` when the expression has another shape.
fn curve(expression: &str) -> Option<Result<Value, ParseErrorKind>> {
    let arguments = expression
        .strip_prefix("CubicBezierEasing(")?
        .strip_suffix(')')?;
    let numbers = match arguments
        .split(", ")
        .map(number)
        .collect::<Result<Vec<_>, _>>()
    {
        Ok(numbers) => numbers,
        Err(error) => return Some(Err(error)),
    };
    let points: [f32; 4] = numbers.try_into().ok()?;
    Some(Ok(Value::CubicBezier(points)))
}

/// `Color(red = 0, green = 0, blue = 0)`; `None` when the expression is not a `Color(...)` call of exactly these
/// three named channels, in this order.
fn srgb(expression: &str) -> Option<Result<[u8; 3], ParseErrorKind>> {
    let arguments = expression.strip_prefix("Color(")?.strip_suffix(')')?;
    let mut channels = [0_u8; 3];
    let mut parts = arguments.split(", ");
    for (channel, label) in channels.iter_mut().zip(["red = ", "green = ", "blue = "]) {
        let literal = parts.next()?.strip_prefix(label)?;
        match self::channel(literal) {
            Ok(value) => *channel = value,
            Err(error) => return Some(Err(error)),
        }
    }
    if parts.next().is_some() {
        return None;
    }
    Some(Ok(channels))
}

/// `PaletteTokens.Neutral98`, a token of another object, or `Primary`, a token of `object` itself; `None` when the
/// expression is neither.
fn reference(expression: &str, object: &str) -> Option<Result<Reference, ParseErrorKind>> {
    let (owner, token) = expression.split_once('.').unwrap_or((object, expression));
    // A second dot (`a.b.C`) or a call (`X.copy(...)`) is another form, not a bad name.
    if token.is_empty() || !token.chars().all(|c| c.is_ascii_alphanumeric()) {
        return None;
    }
    Some(checked_name(owner).and_then(|object| {
        Ok(Reference {
            object,
            token: checked_name(token)?,
        })
    }))
}

fn push(
    object: &mut TokenObject,
    seen: &mut HashSet<String>,
    token: Token,
) -> Result<(), ParseErrorKind> {
    if !seen.insert(token.name.clone()) {
        return Err(ParseErrorKind::Duplicate(token.name));
    }
    object.tokens.push(token);
    Ok(())
}

fn checked_name(name: &str) -> Result<String, ParseErrorKind> {
    let mut chars = name.chars();
    let starts_upper = chars.next().is_some_and(|c| c.is_ascii_uppercase());
    if starts_upper && chars.all(|c| c.is_ascii_alphanumeric()) {
        Ok(name.to_owned())
    } else {
        Err(ParseErrorKind::BadName(name.to_owned()))
    }
}

/// A Kotlin `Float` (`0.8f`) or `Double` (`700.0`) literal, as the `f32` NSH takes.
fn number(literal: &str) -> Result<f32, ParseErrorKind> {
    let bad = || ParseErrorKind::BadNumber(literal.to_owned());
    let (digits, is_float) = match literal.strip_suffix('f') {
        Some(digits) => (digits, true),
        None => (literal, false),
    };
    // Only plain decimals with a fraction: Rust's parser would also take `inf`, `NaN` or `1e5`, and an integer
    // literal is a Kotlin `Int` this reader has no use for yet.
    let unsigned = digits.strip_prefix('-').unwrap_or(digits);
    let (whole, fraction) = unsigned.split_once('.').ok_or_else(bad)?;
    let all_digits = |part: &str| !part.is_empty() && part.chars().all(|c| c.is_ascii_digit());
    if !all_digits(whole) || !all_digits(fraction) {
        return Err(bad());
    }
    let narrow: f32 = digits.parse().map_err(|_| bad())?;
    if !is_float {
        let wide: f64 = digits.parse().map_err(|_| bad())?;
        if f64::from(narrow).to_bits() != wide.to_bits() {
            return Err(ParseErrorKind::Inexact(literal.to_owned()));
        }
    }
    Ok(narrow)
}

/// The number before Kotlin's `.sp`, an `Int` (`16`) or a `Double` (`0.5`, `-0.2`), as the `Float` androidx makes
/// of it: `Int.sp` and `Double.sp` both call `toFloat()` (androidx `TextUnit.kt`), which rounds to the nearest
/// `Float`. A `Double` whose decimal is exactly halfway between two `f32`s is refused: the decimal and the `Double`
/// could round to different ones.
fn sp(literal: &str) -> Result<f32, ParseErrorKind> {
    let bad = || ParseErrorKind::BadNumber(literal.to_owned());
    let unsigned = literal.strip_prefix('-').unwrap_or(literal);
    let all_digits = |part: &str| !part.is_empty() && part.chars().all(|c| c.is_ascii_digit());
    let plain = match unsigned.split_once('.') {
        Some((whole, fraction)) => all_digits(whole) && all_digits(fraction),
        None => all_digits(unsigned),
    };
    if !plain {
        return Err(bad());
    }
    let narrow: f32 = literal.parse().map_err(|_| bad())?;
    let wide: f64 = literal.parse().map_err(|_| bad())?;
    // `narrow` is the `f32` nearest the decimal. It is also the one nearest the `Double` when the `Double` lies
    // strictly between the midpoints to its neighbours; each midpoint has 25 significant bits, so `f64` holds it
    // exactly.
    let below = f64::midpoint(f64::from(narrow), f64::from(narrow.next_down()));
    let above = f64::midpoint(f64::from(narrow), f64::from(narrow.next_up()));
    if below < wide && wide < above {
        Ok(narrow)
    } else {
        Err(ParseErrorKind::Inexact(literal.to_owned()))
    }
}

/// An 8-bit color channel: a plain integer from 0 to 255.
fn channel(literal: &str) -> Result<u8, ParseErrorKind> {
    let bad = || ParseErrorKind::BadChannel(literal.to_owned());
    // `u8::from_str` would also take a leading `+`.
    if !literal.chars().all(|c| c.is_ascii_digit()) {
        return Err(bad());
    }
    literal.parse().map_err(|_| bad())
}

#[cfg(test)]
mod tests {
    use super::*;

    const HEADER: &str = "/*\n * Copyright\n */\n// VERSION: v0_1\n// GENERATED CODE\n\npackage a.b\n\nimport a.C\n\n";

    fn file(body: &str) -> String {
        format!("{HEADER}internal object SampleTokens {{\n{body}}}\n")
    }

    fn error_kind(body: &str) -> ParseErrorKind {
        parse(&file(body)).unwrap_err().kind
    }

    #[test]
    fn reads_numbers_and_curves_in_file_order() {
        let source = file(
            "    const val DurationShort1 = 50.0\n    const val SpringDamping = 0.8f\n    inline val Easing: CubicBezierEasing\n        get() = CubicBezierEasing(0.2f, 0.0f, 0.0f, 1.0f)\n\n",
        );
        let object = parse(&source).unwrap();
        assert_eq!(object.name, "SampleTokens");
        assert_eq!(object.version.as_deref(), Some("v0_1"));
        assert_eq!(
            object.tokens,
            vec![
                Token {
                    name: "DurationShort1".into(),
                    value: Value::Number(50.0)
                },
                Token {
                    name: "SpringDamping".into(),
                    value: Value::Number(0.8)
                },
                Token {
                    name: "Easing".into(),
                    value: Value::CubicBezier([0.2, 0.0, 0.0, 1.0])
                },
            ]
        );
    }

    fn color(object: &str, token: &str) -> Value {
        Value::Reference(
            Kind::Color,
            Reference {
                object: object.into(),
                token: token.into(),
            },
        )
    }

    fn only_value(body: &str) -> Value {
        let mut tokens = parse(&file(body)).unwrap().tokens;
        assert_eq!(tokens.len(), 1);
        tokens.remove(0).value
    }

    #[test]
    fn reads_colors_and_color_references() {
        let source = file(
            "    inline val Neutral98: Color\n        get() = Color(red = 254, green = 247, blue = 0)\n\n    inline val Background: androidx.compose.ui.graphics.Color\n        get() = PaletteTokens.Neutral98\n\n    inline val Error: Color\n        get() = PaletteTokens.Error40\n",
        );
        let tokens = parse(&source).unwrap().tokens;
        assert_eq!(
            tokens,
            vec![
                Token {
                    name: "Neutral98".into(),
                    value: Value::Srgb([254, 247, 0]),
                },
                Token {
                    name: "Background".into(),
                    value: color("PaletteTokens", "Neutral98"),
                },
                Token {
                    name: "Error".into(),
                    value: color("PaletteTokens", "Error40"),
                },
            ]
        );
    }

    #[test]
    fn keeps_each_channel_in_its_place() {
        assert_eq!(
            only_value(
                "    inline val C: Color\n        get() = Color(red = 1, green = 2, blue = 255)\n"
            ),
            Value::Srgb([1, 2, 255])
        );
    }

    #[test]
    fn rejects_a_channel_out_of_range_or_not_a_plain_integer() {
        for literal in ["256", "-1", "+1", "1.0", "0x10", "", "1f"] {
            assert_eq!(
                error_kind(&format!(
                    "    inline val C: Color\n        get() = Color(red = 0, green = {literal}, blue = 0)\n"
                )),
                ParseErrorKind::BadChannel(literal.into()),
                "{literal}"
            );
        }
        assert_eq!(channel("0"), Ok(0));
        assert_eq!(channel("255"), Ok(255));
    }

    #[test]
    fn rejects_a_color_call_of_another_shape() {
        for expression in [
            "Color(red = 0, green = 0)",
            "Color(red = 0, green = 0, blue = 0, alpha = 0)",
            "Color(green = 0, red = 0, blue = 0)",
            "Color(0, 0, 0)",
            "Color(0xFF000000)",
            "Color(red = 0, green = 0, blue = 0",
            "Primary()",
            "PaletteTokens.Neutral98.copy(alpha = 0.5f)",
            "PaletteTokens.",
            "a.b.C",
        ] {
            assert_eq!(
                error_kind(&format!(
                    "    inline val C: Color\n        get() = {expression}\n"
                )),
                ParseErrorKind::Unsupported(format!("get() = {expression}")),
                "{expression}"
            );
        }
    }

    #[test]
    fn a_bare_name_is_a_token_of_the_same_object() {
        assert_eq!(
            only_value("    inline val SurfaceTint: Color\n        get() = Primary\n"),
            color("SampleTokens", "Primary")
        );
        assert_eq!(
            error_kind("    inline val C: Color\n        get() = primary\n"),
            ParseErrorKind::BadName("primary".into())
        );
    }

    #[test]
    fn a_reference_names_two_pascal_case_identifiers() {
        assert_eq!(
            error_kind("    inline val C: Color\n        get() = paletteTokens.Neutral98\n"),
            ParseErrorKind::BadName("paletteTokens".into())
        );
        assert_eq!(
            error_kind("    inline val C: Color\n        get() = PaletteTokens.neutral98\n"),
            ParseErrorKind::BadName("neutral98".into())
        );
    }

    #[test]
    fn a_color_needs_a_color_type_and_a_reference_needs_a_color() {
        // The type decides the form: a color call or a reference under another type is not guessed.
        assert_eq!(
            error_kind("    inline val C: Dp\n        get() = PaletteTokens.Neutral98\n"),
            ParseErrorKind::Unsupported("get() = PaletteTokens.Neutral98".into())
        );
        assert_eq!(
            error_kind(
                "    inline val C: CubicBezierEasing\n        get() = Color(red = 0, green = 0, blue = 0)\n"
            ),
            ParseErrorKind::Unsupported("get() = Color(red = 0, green = 0, blue = 0)".into())
        );
        assert_eq!(
            error_kind(
                "    inline val C: TextStyle\n        get() = TypographyTokens.LabelLarge\n"
            ),
            ParseErrorKind::Unsupported("get() = TypographyTokens.LabelLarge".into())
        );
    }

    #[test]
    fn reads_lengths_in_dp() {
        assert_eq!(
            only_value(
                "    inline val Level2: androidx.compose.ui.unit.Dp\n        get() = 3.0.dp\n"
            ),
            Value::Dp(3.0)
        );
    }

    #[test]
    fn rejects_a_length_of_another_shape() {
        let error = |expression: &str| {
            error_kind(&format!(
                "    inline val L: androidx.compose.ui.unit.Dp\n        get() = {expression}\n"
            ))
        };
        assert_eq!(
            error("3.0"),
            ParseErrorKind::Unsupported("get() = 3.0".into())
        );
        assert_eq!(
            error("3.0.sp"),
            ParseErrorKind::Unsupported("get() = 3.0.sp".into())
        );
        assert_eq!(
            error("ElevationTokens.Level0.copy()"),
            ParseErrorKind::Unsupported("get() = ElevationTokens.Level0.copy()".into())
        );
        assert_eq!(error("3.dp"), ParseErrorKind::BadNumber("3".into()));
        assert_eq!(error("0.1.dp"), ParseErrorKind::Inexact("0.1".into()));
        // A `Dp` named by its short type is not a form these files use.
        assert_eq!(
            error_kind("    inline val L: Dp\n        get() = 3.0.dp\n"),
            ParseErrorKind::Unsupported("get() = 3.0.dp".into())
        );
    }

    #[test]
    fn reads_shapes_and_corner_sizes_on_one_line() {
        let source = file(
            "    val CornerFull = CircleShape\n    val CornerNone = RectangleShape\n    val CornerSmall = RoundedCornerShape(8.0.dp)\n    val CornerValueSmall = CornerSize(8.0.dp)\n",
        );
        let values: Vec<Value> = parse(&source)
            .unwrap()
            .tokens
            .into_iter()
            .map(|token| token.value)
            .collect();
        assert_eq!(
            values,
            [
                Value::Shape(Shape::Circle),
                Value::Shape(Shape::Rectangle),
                Value::Shape(Shape::Rounded([8.0; 4])),
                Value::Dp(8.0),
            ]
        );
    }

    #[test]
    fn reads_a_shape_over_several_lines_with_each_corner_in_place() {
        // androidx `ShapeTokens.CornerLargeEnd`: every corner is named, in this order, with a trailing comma.
        let body = "    val CornerLargeEnd =\n        RoundedCornerShape(\n            topStart = 0.0.dp,\n            topEnd = 16.0.dp,\n            bottomEnd = 12.0.dp,\n            bottomStart = 4.0.dp,\n        )\n    val CornerFull =\n        CircleShape\n";
        let tokens = parse(&file(body)).unwrap().tokens;
        assert_eq!(
            tokens,
            [
                Token {
                    name: "CornerLargeEnd".into(),
                    value: Value::Shape(Shape::Rounded([0.0, 16.0, 12.0, 4.0])),
                },
                Token {
                    name: "CornerFull".into(),
                    value: Value::Shape(Shape::Circle),
                },
            ]
        );
    }

    #[test]
    fn rejects_a_shape_of_another_form() {
        let unsupported = |expression: &str| {
            assert_eq!(
                error_kind(&format!("    val S = {expression}\n")),
                ParseErrorKind::Unsupported(format!("val S = {expression}")),
                "{expression}"
            );
        };
        // A percentage, a size in another unit, two radii, a corner out of androidx's order, a corner missing, an
        // unknown corner, a shape androidx has but these files do not use, and a number with no shape.
        unsupported("RoundedCornerShape(50)");
        unsupported("RoundedCornerShape(4.0.sp)");
        unsupported("RoundedCornerShape(4.0.dp, 8.0.dp)");
        unsupported("RoundedCornerShape(topStart = 4.0.dp)");
        unsupported(
            "RoundedCornerShape(topEnd = 4.0.dp, topStart = 4.0.dp, bottomEnd = 0.0.dp, bottomStart = 0.0.dp)",
        );
        unsupported("RoundedCornerShape(topStart = 4.0.dp, topEnd = 4.0.dp, bottomEnd = 0.0.dp)");
        unsupported(
            "RoundedCornerShape(topLeft = 4.0.dp, topEnd = 4.0.dp, bottomEnd = 0.0.dp, bottomStart = 0.0.dp)",
        );
        unsupported("CutCornerShape(4.0.dp)");
        unsupported("CornerSize(50)");
        unsupported("CornerSize(4.0.dp).copy()");
        unsupported("4.0");
        // A value that opens a parenthesis it does not close on its own line.
        unsupported("RoundedCornerShape(");
    }

    #[test]
    fn a_shape_with_a_bad_number_or_name_reports_it() {
        assert_eq!(
            error_kind("    val S = RoundedCornerShape(4.dp)\n"),
            ParseErrorKind::BadNumber("4".into())
        );
        assert_eq!(
            error_kind("    val S = CornerSize(0.1.dp)\n"),
            ParseErrorKind::Inexact("0.1".into())
        );
        assert_eq!(
            error_kind(
                "    val S =\n        RoundedCornerShape(\n            topStart = 4.dp,\n            topEnd = 4.0.dp,\n            bottomEnd = 0.0.dp,\n            bottomStart = 0.0.dp,\n        )\n"
            ),
            ParseErrorKind::BadNumber("4".into())
        );
        assert_eq!(
            error_kind("    val lower = CircleShape\n"),
            ParseErrorKind::BadName("lower".into())
        );
        assert_eq!(
            error_kind("    val lower =\n        CircleShape\n"),
            ParseErrorKind::BadName("lower".into())
        );
        assert_eq!(
            error_kind("    val S = CircleShape\n    val S = RectangleShape\n"),
            ParseErrorKind::Duplicate("S".into())
        );
    }

    #[test]
    fn a_shape_that_never_closes_is_an_error_at_the_last_line() {
        let source = format!(
            "{HEADER}internal object SampleTokens {{\n    val S =\n        RoundedCornerShape(\n"
        );
        let error = parse(&source).unwrap_err();
        assert_eq!(error.kind, ParseErrorKind::UnclosedValue("S".into()));
        assert_eq!(error.line, source.lines().count());
    }

    #[test]
    fn a_shape_over_several_lines_reports_the_line_that_closes_it() {
        let body =
            "    val S =\n        RoundedCornerShape(\n            topStart = 4.0.dp,\n        )\n";
        let error = parse(&file(body)).unwrap_err();
        assert_eq!(
            error.kind,
            ParseErrorKind::Unsupported("RoundedCornerShape(topStart = 4.0.dp,)".into())
        );
        let closing_line = HEADER.lines().count() + 5;
        assert_eq!(error.line, closing_line);
    }

    fn getter(ty: &str, expression: &str) -> String {
        format!("    inline val X: {ty}\n        get() = {expression}\n")
    }

    #[test]
    fn reads_text_units_as_the_float_androidx_makes() {
        let sp = |expression: &str| match only_value(&getter(
            "androidx.compose.ui.unit.TextUnit",
            expression,
        )) {
            Value::Sp(size) => size.to_bits(),
            other => panic!("{expression}: {other:?}"),
        };
        // An `Int`, a `Double`, a negative `Double` and zero, from `TypeScaleTokens`.
        assert_eq!(sp("16.sp"), 16.0_f32.to_bits());
        assert_eq!(sp("24.0.sp"), 24.0_f32.to_bits());
        assert_eq!(sp("-0.2.sp"), (-0.2_f32).to_bits());
        assert_eq!(sp("0.sp"), 0.0_f32.to_bits());
        // A `Double` with no exact `f32`: androidx's `toFloat()` keeps the nearest one.
        assert_eq!(sp("0.1.sp"), 0.1_f32.to_bits());
    }

    #[test]
    fn rejects_a_text_unit_of_another_form() {
        let error =
            |expression: &str| error_kind(&getter("androidx.compose.ui.unit.TextUnit", expression));
        assert_eq!(
            error("16.em"),
            ParseErrorKind::Unsupported("get() = 16.em".into())
        );
        assert_eq!(
            error("16"),
            ParseErrorKind::Unsupported("get() = 16".into())
        );
        for literal in [
            "1e5", ".5", "5.", "+1", "", "0x10", "1_000", "1.0f", "--1", "NaN",
        ] {
            assert_eq!(
                error(&format!("{literal}.sp")),
                ParseErrorKind::BadNumber(literal.into()),
                "{literal}"
            );
        }
        // A `TextUnit` named by its short type is not a form these files use.
        assert_eq!(
            error_kind(&getter("TextUnit", "16.sp")),
            ParseErrorKind::Unsupported("get() = 16.sp".into())
        );
    }

    #[test]
    fn refuses_a_text_unit_halfway_between_two_floats() {
        // 1 + 2^-24 lies exactly halfway between 1.0 and the next `f32`, and 1 - 2^-25 halfway between 1.0 and the
        // one before. A `Double` holds both exactly; which `f32` androidx gets would depend on the rounding.
        for literal in ["1.000000059604644775390625", "0.9999999701976776123046875"] {
            assert_eq!(
                sp(literal),
                Err(ParseErrorKind::Inexact(literal.into())),
                "{literal}"
            );
        }
        // Their neighbours a little inside round to 1.0 either way.
        assert_eq!(sp("1.00000005960464").unwrap().to_bits(), 1.0_f32.to_bits());
        assert_eq!(sp("0.99999997019768").unwrap().to_bits(), 1.0_f32.to_bits());
        assert_eq!(sp("-0.5").unwrap().to_bits(), (-0.5_f32).to_bits());
    }

    #[test]
    fn reads_font_families_weights_and_references_to_them() {
        for ty in ["FontFamily", "androidx.compose.ui.text.font.FontFamily"] {
            assert_eq!(
                only_value(&getter(ty, "FontFamily.SansSerif")),
                Value::FontFamily(FontFamily::SansSerif)
            );
            assert_eq!(
                only_value(&getter(ty, "TypefaceTokens.Plain")),
                Value::Reference(
                    Kind::FontFamily,
                    Reference {
                        object: "TypefaceTokens".into(),
                        token: "Plain".into()
                    }
                )
            );
        }
        for ty in ["FontWeight", "androidx.compose.ui.text.font.FontWeight"] {
            // androidx `FontWeight.kt`: `Normal = W400`, `Medium = W500`, `Bold = W700`.
            assert_eq!(
                only_value(&getter(ty, "FontWeight.Normal")),
                Value::FontWeight(400)
            );
            assert_eq!(
                only_value(&getter(ty, "FontWeight.Medium")),
                Value::FontWeight(500)
            );
            assert_eq!(
                only_value(&getter(ty, "FontWeight.Bold")),
                Value::FontWeight(700)
            );
            assert_eq!(
                only_value(&getter(ty, "WeightBold")),
                Value::Reference(
                    Kind::FontWeight,
                    Reference {
                        object: "SampleTokens".into(),
                        token: "WeightBold".into()
                    }
                )
            );
        }
    }

    #[test]
    fn rejects_a_family_or_weight_it_does_not_know() {
        for (ty, expression) in [
            ("FontFamily", "FontFamily.Serif"),
            ("FontFamily", "FontFamily.Default"),
            ("FontFamily", "FontFamily(Font(1))"),
            ("FontWeight", "FontWeight.W600"),
            ("FontWeight", "FontWeight.Light"),
            ("FontWeight", "FontWeight(400)"),
        ] {
            assert_eq!(
                error_kind(&getter(ty, expression)),
                ParseErrorKind::Unsupported(format!("get() = {expression}")),
                "{expression}"
            );
        }
    }

    #[test]
    fn a_line_comment_in_the_object_is_skipped_and_a_block_comment_is_not() {
        let tokens = parse(&file("    // A note.\n    const val A = 1.0\n"))
            .unwrap()
            .tokens;
        assert_eq!(tokens.len(), 1);
        assert_eq!(
            error_kind("    /* A note. */\n    const val A = 1.0\n"),
            ParseErrorKind::Unsupported("/* A note. */".into())
        );
    }

    #[test]
    fn reads_a_reference_to_a_length() {
        assert_eq!(
            only_value(&getter(
                "androidx.compose.ui.unit.Dp",
                "ElevationTokens.Level1"
            )),
            Value::Reference(
                Kind::Length,
                Reference {
                    object: "ElevationTokens".into(),
                    token: "Level1".into(),
                },
            )
        );
        // A negative number with no unit is neither a length nor a reference.
        assert_eq!(
            error_kind(&getter("androidx.compose.ui.unit.Dp", "-1.0")),
            ParseErrorKind::Unsupported("get() = -1.0".into())
        );
    }

    fn key_file(class: &str, body: &str) -> String {
        format!(
            "{HEADER}@JvmInline internal value class {class}(val id: Int)\n\ninternal object SampleKeyTokens {{\n{body}}}\n"
        )
    }

    #[test]
    fn reads_a_file_of_keys_without_their_ids() {
        let object = parse(&key_file(
            "ColorToken",
            "    val Background = ColorToken(0)\n    val Primary = ColorToken(25)\n",
        ))
        .unwrap();
        assert_eq!(object.name, "SampleKeyTokens");
        assert_eq!(
            object.tokens,
            vec![
                Token {
                    name: "Background".into(),
                    value: Value::Key("ColorToken".into())
                },
                Token {
                    name: "Primary".into(),
                    value: Value::Key("ColorToken".into())
                },
            ]
        );
    }

    #[test]
    fn rejects_a_key_class_or_a_key_of_another_form() {
        let class_error =
            |class: &str| parse(&key_file(class, "    val A = ColorToken(0)\n")).unwrap_err();
        // A class that is not a key (no `Token` suffix) or not a plain name is a form these files do not use.
        for class in ["Color", "colorToken", "Color_Token"] {
            assert_eq!(
                class_error(class).kind,
                ParseErrorKind::Unsupported(format!(
                    "@JvmInline internal value class {class}(val id: Int)"
                )),
                "{class}"
            );
        }
        assert_eq!(
            parse(&format!(
                "{HEADER}@JvmInline internal value class ColorToken(val id: Long)\n\ninternal object A {{\n}}\n"
            ))
            .unwrap_err()
            .kind,
            ParseErrorKind::Unsupported(
                "@JvmInline internal value class ColorToken(val id: Long)".into()
            )
        );
        for expression in [
            "ColorToken()",
            "ColorToken(a)",
            "ColorToken(-1)",
            "ColorToken(1.0)",
            "ColorToken(1",
            "Color(1)",
            "colorToken(1)",
        ] {
            assert_eq!(
                error_kind(&format!("    val A = {expression}\n")),
                ParseErrorKind::Unsupported(format!("val A = {expression}")),
                "{expression}"
            );
        }
    }

    #[test]
    fn reads_a_color_role_a_shape_key_or_a_typography_key_named_by_its_key_object() {
        let reference = |kind, object: &str, token: &str| {
            Value::Reference(
                kind,
                Reference {
                    object: object.into(),
                    token: token.into(),
                },
            )
        };
        assert_eq!(
            only_value(&getter("ColorToken", "ColorSchemeKeyTokens.Primary")),
            reference(Kind::ColorRole, "ColorSchemeKeyTokens", "Primary")
        );
        assert_eq!(
            only_value(&getter("ShapeToken", "ShapeKeyTokens.CornerFull")),
            reference(Kind::ShapeKey, "ShapeKeyTokens", "CornerFull")
        );
        assert_eq!(
            only_value(&getter("TypographyToken", "TypographyKeyTokens.LabelLarge")),
            reference(Kind::TypographyKey, "TypographyKeyTokens", "LabelLarge")
        );
        // A key of another key object, or a bare name, is not a form these files use.
        for (ty, expression) in [
            ("ColorToken", "ShapeKeyTokens.CornerFull"),
            ("ShapeToken", "ColorSchemeKeyTokens.Primary"),
            ("ColorToken", "Primary"),
            ("ShapeToken", "CornerFull"),
            ("TypographyToken", "ColorSchemeKeyTokens.Primary"),
            ("ColorToken", "TypographyKeyTokens.LabelLarge"),
            ("TypographyToken", "LabelLarge"),
        ] {
            assert_eq!(
                error_kind(&getter(ty, expression)),
                ParseErrorKind::Unsupported(format!("get() = {expression}")),
                "{ty} = {expression}"
            );
        }
        // A key object with a bad token name reports the name.
        assert_eq!(
            error_kind(&getter("ColorToken", "ColorSchemeKeyTokens.primary")),
            ParseErrorKind::BadName("primary".into())
        );
    }

    #[test]
    fn a_reference_holds_only_values_of_its_kind() {
        let reference = |kind| {
            Value::Reference(
                kind,
                Reference {
                    object: "A".into(),
                    token: "B".into(),
                },
            )
        };
        let values = [
            Value::Srgb([0, 0, 0]),
            Value::FontFamily(FontFamily::SansSerif),
            Value::FontWeight(400),
            Value::Dp(1.0),
            Value::Key("ColorToken".into()),
            Value::Key("ShapeToken".into()),
            Value::Sp(1.0),
            Value::Key("TypographyToken".into()),
        ];
        let kinds = [
            Kind::Color,
            Kind::FontFamily,
            Kind::FontWeight,
            Kind::Length,
            Kind::ColorRole,
            Kind::ShapeKey,
            Kind::TextUnit,
            Kind::TypographyKey,
        ];
        for (index, kind) in kinds.into_iter().enumerate() {
            for (other, value) in values.iter().enumerate() {
                assert_eq!(kind.holds(value), index == other, "{kind} holds {value:?}");
            }
            for other in kinds {
                assert_eq!(
                    kind.holds(&reference(other)),
                    kind == other,
                    "{kind} holds {other}"
                );
            }
            assert!(!kind.holds(&Value::Number(1.0)));
            assert!(!kind.holds(&Value::Key("OtherToken".into())));
            assert!(!kind.holds(&Value::TextStyle(Box::new(style("A", "B")))));
        }
        assert_eq!(
            kinds.map(|kind| kind.to_string()),
            [
                "color",
                "font family",
                "font weight",
                "length",
                "color role",
                "shape key",
                "text unit",
                "typography key"
            ]
        );
    }

    /// The text style `name` whose five properties are tokens of `object`, as `TypographyTokens.kt` writes them.
    fn style(object: &str, name: &str) -> TextStyle {
        let reference = |suffix: &str| Reference {
            object: object.into(),
            token: format!("{name}{suffix}"),
        };
        TextStyle {
            font: reference("Font"),
            weight: reference("Weight"),
            size: reference("Size"),
            line_height: reference("LineHeight"),
            tracking: reference("Tracking"),
        }
    }

    /// The lines of the text style `name` in `TypographyTokens.kt`, each property naming the token its line gives.
    fn style_lines(name: &str, properties: [&str; 5]) -> String {
        let [font, weight, size, line_height, tracking] = properties;
        format!(
            "    val {name}: TextStyle\n        inline get() =\n            DefaultTextStyle.copy(\n                fontFamily = fontFamily ?: {font},\n                fontWeight = {weight},\n                fontSize = {size},\n                lineHeight = {line_height},\n                letterSpacing = {tracking},\n            )\n"
        )
    }

    fn typescale(name: &str) -> [String; 5] {
        ["Font", "Weight", "Size", "LineHeight", "Tracking"]
            .map(|suffix| format!("TypeScaleTokens.{name}{suffix}"))
    }

    const DEFAULT_STYLE: &str = "\ninternal val DefaultLineHeightStyle =\n    LineHeightStyle(alignment = LineHeightStyle.Alignment.Center, trim = LineHeightStyle.Trim.None)\n\ninternal val DefaultTextStyle =\n    TextStyle.Default.copy(\n        platformStyle = defaultPlatformTextStyle(),\n        lineHeightStyle = DefaultLineHeightStyle,\n    )\n";

    /// A `TypographyTokens.kt` of `body`, followed by `trailer`.
    fn typography(body: &str, trailer: &str) -> String {
        format!(
            "{HEADER}internal class TypographyTokens(val fontFamily: FontFamily? = null) {{\n{body}}}\n{trailer}"
        )
    }

    fn style_error(properties: [&str; 5]) -> ParseError {
        parse(&typography(
            &style_lines("BodyLarge", properties),
            DEFAULT_STYLE,
        ))
        .unwrap_err()
    }

    #[test]
    fn reads_a_class_of_text_styles_and_its_default_style() {
        let [font, weight, size, line_height, tracking] = typescale("BodyLarge");
        let [
            label_font,
            label_weight,
            label_size,
            label_line_height,
            label_tracking,
        ] = typescale("LabelLarge");
        let body = format!(
            "{}\n{}",
            style_lines(
                "BodyLarge",
                [&font, &weight, &size, &line_height, &tracking]
            ),
            style_lines(
                "LabelLarge",
                [
                    &label_font,
                    &label_weight,
                    &label_size,
                    &label_line_height,
                    &label_tracking
                ]
            )
        );
        let object = parse(&typography(&body, DEFAULT_STYLE)).unwrap();
        assert_eq!(object.name, "TypographyTokens");
        assert_eq!(
            object.tokens,
            vec![
                Token {
                    name: "BodyLarge".into(),
                    value: Value::TextStyle(Box::new(style("TypeScaleTokens", "BodyLarge")))
                },
                Token {
                    name: "LabelLarge".into(),
                    value: Value::TextStyle(Box::new(style("TypeScaleTokens", "LabelLarge")))
                },
            ]
        );
        // The default style may also be left out, and blank lines may follow it.
        assert!(parse(&typography(&body, "")).is_ok());
        assert!(parse(&typography(&body, &format!("{DEFAULT_STYLE}\n\n"))).is_ok());
        let properties: Vec<Kind> = style("A", "B")
            .properties()
            .iter()
            .map(|(kind, _)| *kind)
            .collect();
        assert_eq!(
            properties,
            [
                Kind::FontFamily,
                Kind::FontWeight,
                Kind::TextUnit,
                Kind::TextUnit,
                Kind::TextUnit
            ]
        );
    }

    #[test]
    fn a_text_style_takes_only_the_tokens_of_its_own_name_in_order() {
        let [font, weight, size, line_height, tracking] = typescale("BodyLarge");
        let unsupported = |line: usize, text: &str| ParseError {
            line,
            kind: ParseErrorKind::Unsupported(text.into()),
        };
        // The style's first property is on line 15 of the file, after the header, the class and two getter lines.
        let other = "TypeScaleTokens.BodyMediumWeight";
        assert_eq!(
            style_error([&font, other, &size, &line_height, &tracking]),
            unsupported(16, &format!("fontWeight = {other},"))
        );
        // The properties in another order.
        assert_eq!(
            style_error([&font, &size, &weight, &line_height, &tracking]),
            unsupported(16, &format!("fontWeight = {size},"))
        );
        // A token of the class itself, with no object.
        assert_eq!(
            style_error([&font, &weight, "BodyLargeSize", &line_height, &tracking]),
            unsupported(17, "fontSize = BodyLargeSize,")
        );
        // A token name that is not one.
        assert_eq!(
            style_error([
                &font,
                &weight,
                &size,
                "TypeScaleTokens.bodyLargeLineHeight",
                &tracking
            ])
            .kind,
            ParseErrorKind::BadName("bodyLargeLineHeight".into())
        );
        // A call, not a token.
        assert_eq!(
            style_error([
                &font,
                &weight,
                &size,
                &line_height,
                "TypeScaleTokens.BodyLargeTracking.copy()"
            ]),
            unsupported(
                19,
                "letterSpacing = TypeScaleTokens.BodyLargeTracking.copy(),"
            )
        );
        // Tokens of two objects.
        assert_eq!(
            style_error([
                &font,
                &weight,
                &size,
                &line_height,
                "OtherTokens.BodyLargeTracking"
            ]),
            unsupported(
                20,
                "a text style whose tokens are not all of `TypeScaleTokens`"
            )
        );
    }

    #[test]
    fn a_text_style_has_exactly_its_getter_lines_and_the_family_an_app_may_override() {
        let [font, weight, size, line_height, tracking] = typescale("BodyLarge");
        let lines = style_lines(
            "BodyLarge",
            [&font, &weight, &size, &line_height, &tracking],
        );
        let error = |from: &str, to: &str| {
            assert_eq!(lines.matches(from).count(), 1, "{from}");
            parse(&typography(&lines.replace(from, to), DEFAULT_STYLE)).unwrap_err()
        };
        let unsupported = |text: &str| ParseErrorKind::Unsupported(text.into());
        assert_eq!(
            error("inline get() =", "get() =").kind,
            unsupported("get() =")
        );
        assert_eq!(
            error("DefaultTextStyle.copy(", "TextStyle(").kind,
            unsupported("TextStyle(")
        );
        assert_eq!(
            error("fontFamily = fontFamily ?: ", "fontFamily = ").kind,
            unsupported(&format!("fontFamily = {font},"))
        );
        // A property with no comma, a sixth property, and no closing parenthesis before the class ends.
        assert_eq!(
            error(&format!("{tracking},"), &tracking).kind,
            unsupported(&format!("letterSpacing = {tracking}"))
        );
        assert_eq!(
            error(
                "            )\n",
                "                fontStyle = Italic,\n            )\n"
            )
            .kind,
            unsupported("fontStyle = Italic,")
        );
        assert_eq!(error("            )\n", "").kind, unsupported("}"));
        // A style that never ends, at the end of the file.
        let open = lines.replace("            )\n", "");
        assert_eq!(
            parse(&format!(
                "{HEADER}internal class TypographyTokens(val fontFamily: FontFamily? = null) {{\n{open}"
            ))
            .unwrap_err()
            .kind,
            ParseErrorKind::UnclosedValue("BodyLarge".into())
        );
        // The same style twice.
        assert_eq!(
            parse(&typography(&format!("{lines}{lines}"), ""))
                .unwrap_err()
                .kind,
            ParseErrorKind::Duplicate("BodyLarge".into())
        );
        // A class of another parameter.
        assert_eq!(
            parse(&typography(&lines, "").replace("FontFamily? = null", "FontFamily"))
                .unwrap_err()
                .kind,
            unsupported("internal class TypographyTokens(val fontFamily: FontFamily) {")
        );
    }

    #[test]
    fn only_the_whole_default_style_may_follow_the_class() {
        let [font, weight, size, line_height, tracking] = typescale("BodyLarge");
        let lines = style_lines(
            "BodyLarge",
            [&font, &weight, &size, &line_height, &tracking],
        );
        let trailer_error = |trailer: &str| parse(&typography(&lines, trailer)).unwrap_err();
        let trailing = |text: &str| ParseErrorKind::TrailingContent(text.into());
        assert_eq!(
            trailer_error(&DEFAULT_STYLE.replace("Center", "Top")).kind,
            trailing(
                "LineHeightStyle(alignment = LineHeightStyle.Alignment.Top, trim = LineHeightStyle.Trim.None)"
            )
        );
        assert_eq!(
            trailer_error("internal val DefaultTextStyle =\n").kind,
            trailing("internal val DefaultTextStyle =")
        );
        assert_eq!(
            trailer_error(&format!("{DEFAULT_STYLE}internal val Other = 1\n")).kind,
            trailing("internal val Other = 1")
        );
        // Cut short, it never closes.
        let cut = DEFAULT_STYLE.replace("    )\n", "");
        assert_eq!(
            trailer_error(&cut).kind,
            ParseErrorKind::UnclosedValue("DefaultTextStyle".into())
        );
    }

    #[test]
    fn a_curve_with_a_bad_number_reports_the_number() {
        assert_eq!(
            error_kind(
                "    inline val E: CubicBezierEasing\n        get() = CubicBezierEasing(0.2f, 0.0f, x, 1.0f)\n"
            ),
            ParseErrorKind::BadNumber("x".into())
        );
    }

    #[test]
    fn a_float_literal_becomes_the_nearest_f32() {
        assert_eq!(number("0.8f").unwrap().to_bits(), 0.8_f32.to_bits());
        assert_eq!(number("-0.25f").unwrap().to_bits(), (-0.25_f32).to_bits());
    }

    #[test]
    fn rejects_a_double_that_f32_cannot_hold() {
        assert_eq!(number("0.1"), Err(ParseErrorKind::Inexact("0.1".into())));
        assert_eq!(number("700.0").unwrap().to_bits(), 700.0_f32.to_bits());
    }

    #[test]
    fn rejects_numbers_that_are_not_plain_decimals() {
        for literal in ["2", "1e5", "1.0e5f", "inf", "NaN", ".5f", "5.f", "0x10", ""] {
            assert_eq!(
                number(literal),
                Err(ParseErrorKind::BadNumber(literal.into())),
                "{literal}"
            );
        }
    }

    #[test]
    fn rejects_an_unknown_form_instead_of_skipping_it() {
        assert_eq!(
            error_kind("    val Shape = CutCornerShape(4.0.dp)\n"),
            ParseErrorKind::Unsupported("val Shape = CutCornerShape(4.0.dp)".into())
        );
        assert_eq!(
            error_kind("    inline val Size: Dp\n        get() = 4.0.dp\n"),
            ParseErrorKind::Unsupported("get() = 4.0.dp".into())
        );
        assert_eq!(
            error_kind(
                "    inline val E: CubicBezierEasing\n        get() = CubicBezierEasing(0.2f, 0.0f, 1.0f)\n"
            ),
            ParseErrorKind::Unsupported("get() = CubicBezierEasing(0.2f, 0.0f, 1.0f)".into())
        );
    }

    #[test]
    fn reports_the_line_of_the_error() {
        let error = parse(&file("    const val A = 1.0\n    const val B = oops\n")).unwrap_err();
        let line_of_b = HEADER.lines().count() + 3;
        assert_eq!(error.line, line_of_b);
    }

    #[test]
    fn rejects_bad_names_duplicates_and_trailing_content() {
        assert_eq!(
            error_kind("    const val lower = 1.0\n"),
            ParseErrorKind::BadName("lower".into())
        );
        assert_eq!(
            error_kind("    const val A = 1.0\n    const val A = 2.0\n"),
            ParseErrorKind::Duplicate("A".into())
        );
        let trailing = format!("{}val Stray = 1\n", file(""));
        assert_eq!(
            parse(&trailing).unwrap_err().kind,
            ParseErrorKind::TrailingContent("val Stray = 1".into())
        );
    }

    #[test]
    fn blank_lines_after_the_object_are_fine() {
        let source = format!("{}\n\n   \n", file("    const val A = 1.0\n"));
        assert_eq!(parse(&source).unwrap().tokens.len(), 1);
    }

    #[test]
    fn every_error_names_its_line_and_its_cause() {
        let cases = [
            (
                ParseErrorKind::Unsupported("x".into()),
                "line 3: unsupported form `x`",
            ),
            (
                ParseErrorKind::BadName("x".into()),
                "line 3: `x` is not a PascalCase token name",
            ),
            (
                ParseErrorKind::BadNumber("x".into()),
                "line 3: `x` is not a supported number",
            ),
            (
                ParseErrorKind::BadChannel("x".into()),
                "line 3: `x` is not a color channel from 0 to 255",
            ),
            (
                ParseErrorKind::Inexact("x".into()),
                "line 3: `x` cannot be held exactly by an f32",
            ),
            (
                ParseErrorKind::MissingGetter("x".into()),
                "line 3: `x` has no `get() = ...` line",
            ),
            (
                ParseErrorKind::UnclosedValue("x".into()),
                "line 3: `x`'s value never closes",
            ),
            (
                ParseErrorKind::Duplicate("x".into()),
                "line 3: `x` is defined twice",
            ),
            (
                ParseErrorKind::TrailingContent("x".into()),
                "line 3: `x` after the object's end",
            ),
            (
                ParseErrorKind::Unterminated,
                "line 3: no complete `internal object` in the file",
            ),
        ];
        for (kind, message) in cases {
            assert_eq!(ParseError { line: 3, kind }.to_string(), message);
        }
    }

    #[test]
    fn rejects_a_getter_without_its_body_and_an_unclosed_object() {
        assert_eq!(
            error_kind("    inline val E: CubicBezierEasing\n    const val A = 1.0\n"),
            ParseErrorKind::MissingGetter("E".into())
        );
        assert_eq!(
            parse("internal object A {\n    const val B = 1.0\n")
                .unwrap_err()
                .kind,
            ParseErrorKind::Unterminated
        );
        assert_eq!(
            parse("package a\n").unwrap_err().kind,
            ParseErrorKind::Unterminated
        );
    }
}
